// Own the vector itself. Wipe its logical secret bytes before releasing storage,
// including local import failures before ownership reaches a CryptoKey slot.
// This does not erase capacity beyond size or other copies of the key.
struct SecretByteVectorDeleter {
  void operator()(std::vector<uint8_t> *bytes) const noexcept {
    if (bytes) {
      if (!bytes->empty()) { OPENSSL_cleanse(bytes->data(), bytes->size()); }
      delete bytes;
    }
  }
};

